        return (dx * dx + dy * dy) ** 0.5

    customers = [i for i in range(1, n) if demand[i] > 0]
    if not customers:
        return []

    routes = [[i] for i in customers]
    route_of = {i: idx for idx, i in enumerate(customers)}
    loads = [demand[i] for i in customers]

    savings = []
    for a in range(len(customers)):
        i = customers[a]
        di0 = d(0, i)
        for b in range(a + 1, len(customers)):
            j = customers[b]
            s = di0 + d(0, j) - d(i, j)
            savings.append((s, i, j))
    savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    def try_merge(ri, rj, i, j):
        if ri == rj:
            return False
        a = routes[ri]
        b = routes[rj]
        if not a or not b:
            return False
        if loads[ri] + loads[rj] > capacity:
            return False
        af, al = a[0], a[-1]
        bf, bl = b[0], b[-1]
        if i == al and j == bf:
            new_route = a + b
        elif i == af and j == bl:
            new_route = list(reversed(a)) + list(reversed(b))
        elif i == af and j == bf:
            new_route = list(reversed(a)) + b
        elif i == al and j == bl:
            new_route = a + list(reversed(b))
        else:
            return False
        routes[ri] = new_route
        loads[ri] += loads[rj]
        for c in new_route:
            route_of[c] = ri
        routes[rj] = []
        loads[rj] = 0
        return True

    for _, i, j in savings:
        ri = route_of[i]
        rj = route_of[j]
        if ri != rj and routes[ri] and routes[rj]:
            try_merge(ri, rj, i, j)

    routes = [r for r in routes if r]
    loads = [sum(demand[c] for c in r) for r in routes]

    assigned = set()
    for r in routes:
        for c in r:
            assigned.add(c)

    missing = [c for c in customers if c not in assigned]
    for c in missing:
        best = None
        for ridx, r in enumerate(routes):
            if loads[ridx] + demand[c] > capacity:
                continue
            prev = 0
            for pos in range(len(r) + 1):
                nxt = 0 if pos == len(r) else r[pos]
                inc = d(prev, c) + d(c, nxt) - d(prev, nxt)
                cand = (inc, ridx, pos)
                if best is None or cand < best:
                    best = cand
                if pos < len(r):
                    prev = r[pos]
        if best is None:
            routes.append([c])
            loads.append(demand[c])
        else:
            _, ridx, pos = best
            routes[ridx].insert(pos, c)
            loads[ridx] += demand[c]

    improved = True
    while improved:
        improved = False

        for i in range(len(routes)):
            if improved:
                break
            ri = routes[i]
            li = loads[i]
            for a in range(len(ri)):
                c = ri[a]
                dc = demand[c]
                pre = 0 if a == 0 else ri[a - 1]
                nxt = 0 if a == len(ri) - 1 else ri[a + 1]
                remove_gain = d(pre, nxt) - d(pre, c) - d(c, nxt)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if loads[j] + dc > capacity:
                        continue
                    best_pos = None
                    best_delta = 0
                    for pos in range(len(rj) + 1):
                        p = 0 if pos == 0 else rj[pos - 1]
                        n2 = 0 if pos == len(rj) else rj[pos]
                        delta = remove_gain + d(p, c) + d(c, n2) - d(p, n2)
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            best_pos = pos
                    if best_pos is not None:
                        new_ri = ri[:a] + ri[a + 1:]
                        new_rj = rj[:best_pos] + [c] + rj[best_pos:]
                        if new_ri:
                            routes[i] = new_ri
                            loads[i] = li - dc
                            routes[j] = new_rj
                            loads[j] += dc
                        else:
                            routes.pop(i)
                            loads.pop(i)
                            if j > i:
                                j -= 1
                            routes[j] = new_rj
                            loads[j] += dc
                        improved = True
                        break
                if improved:
                    break

        if improved:
            continue

        for ridx in range(len(routes)):
            r = routes[ridx]
            best_delta = 0
            best_move = None
            L = len(r)
            for i in range(L - 1):
                a = 0 if i == 0 else r[i - 1]
                b = r[i]
                for k in range(i + 1, L):
                    c = r[k]
                    d2 = 0 if k == L - 1 else r[k + 1]
                    delta = d(a, c) + d(b, d2) - d(a, b) - d(c, d2)
                    if delta < best_delta - 1e-12:
                        best_delta = delta
                        best_move = (i, k)
            if best_move is not None:
                i, k = best_move
                routes[ridx] = r[:i] + list(reversed(r[i:k + 1])) + r[k + 1:]
                improved = True
                break

    cleaned = []
    seen = set()
    for r in routes:
        nr = []
        for c in r:
            if c != 0 and c not in seen:
                nr.append(c)
                seen.add(c)
        if nr:
            cleaned.append(nr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        best = None
        for ridx, r in enumerate(cleaned):
            load = 0
            for x in r:
                load += demand[x]
            if load + demand[c] > capacity:
                continue
            prev = 0
            for pos in range(len(r) + 1):
                nxt = 0 if pos == len(r) else r[pos]
                inc = d(prev, c) + d(c, nxt) - d(prev, nxt)
                cand = (inc, ridx, pos)
                if best is None or cand < best:
                    best = cand
                if pos < len(r):
                    prev = r[pos]
        if best is None:
            cleaned.append([c])
        else:
            _, ridx, pos = best
            cleaned[ridx].insert(pos, c)

    return cleaned
